-- Normalized Approach: Separating User Profile and Order History
CREATE TABLE users (id SERIAL PRIMARY KEY, username VARCHAR(50));
CREATE TABLE orders (id SERIAL PRIMARY KEY, user_id INT REFERENCES users(id), total_amount NUMERIC);

-- Denormalized Approach: Embedding frequently accessed user data directly into orders
CREATE TABLE denormalized_orders (
    id SERIAL PRIMARY KEY,
    user_id INT,
    username VARCHAR(50), -- Denormalized attribute to avoid JOINs
    total_amount NUMERIC
);
